import{_ as i,a0 as p,w as r,s as l,I as n,x as s,a1 as e,A as u,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Ubuntu 中更改鍵盤佈局 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中更改鍵盤佈局 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中更改鍵盤佈局 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中更改鍵盤佈局 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20231129 Change Keyboard Layout in Ubuntu","title":"在 Ubuntu 中更改鍵盤佈局","tag":"202312","desc":""},"relativePath":"202312/20231129 Change Keyboard Layout in Ubuntu.md","filePath":"[post].md"}'),d={name:"202312/20231129 Change Keyboard Layout in Ubuntu.md"};function b(g,t,m,f,k,y){const o=p("Link");return r(),l("div",null,[t[29]||(t[29]=n("h1",{id:"在-ubuntu-中更改鍵盤佈局",tabindex:"-1"},[s("在 Ubuntu 中更改鍵盤佈局 "),n("a",{class:"header-anchor",href:"#在-ubuntu-中更改鍵盤佈局","aria-label":"Permalink to “在 Ubuntu 中更改鍵盤佈局”"},"​")],-1)),t[30]||(t[30]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202312/05/160115uz3s3y093fak0za9.png",alt:""})],-1)),t[31]||(t[31]=n("blockquote",null,[n("p",null,"在 Ubuntu 中擁有多個鍵盤佈局並在它們之間切換非常簡單。下面就教你怎麼做。")],-1)),n("p",null,[t[1]||(t[1]=s("當 ",-1)),e(o,{href:"https://itsfoss.com/install-ubuntu/"},{default:u(()=>[...t[0]||(t[0]=[s("你安裝Ubuntu",-1)])]),_:1}),t[2]||(t[2]=s(" 時，你可以選擇鍵盤佈局。你可能已經默認選擇了美國英語佈局，現在你想將其更改為英國英語、印度英語或你選擇的任何其他鍵盤佈局。",-1))]),t[32]||(t[32]=a('<p>好在你可以在同一個 Ubuntu 系統中擁有多種鍵盤佈局。這是相當方便的。</p><p>在本教程中，你將學習：</p><ul><li>在 Ubuntu 桌面中添加新的鍵盤佈局</li><li>在可用鍵盤佈局之間切換</li><li>刪除額外的鍵盤佈局</li><li>改變鍵盤佈局的命令列方法</li></ul><h3 id="步驟-1-添加新的鍵盤佈局" tabindex="-1">步驟 1：添加新的鍵盤佈局 <a class="header-anchor" href="#步驟-1-添加新的鍵盤佈局" aria-label="Permalink to “步驟 1：添加新的鍵盤佈局”">​</a></h3><p>要更改鍵盤佈局，你需要先在系統上啓用另一個鍵盤佈局。</p><p>進入系統設置。按 Ubuntu 中的 <code>Super</code> 鍵（Windows 鍵）並搜索“Setting”。</p><p><img src="https://itsfoss.com/content/images/2023/11/start-system-settings-ubuntu-1.png" alt=""></p><p>在系統設置中，在左側邊欄中查找 <ruby>鍵盤<rt>Keyboard</rt></ruby>。選擇後，你應該會在 <ruby>輸入源<rt>Input Sources</rt></ruby> 下看到添加新鍵盤佈局的選項。單擊 “+” 號。</p><p><img src="https://itsfoss.com/content/images/2023/11/adding-new-keyboard-layout-ubuntu-1.png" alt="Add new keyboard layout"></p><p>你將看到一些鍵盤選項，但如果單擊三個點，你可以獲得更多選項。你可以在此處滾動瀏覽或搜索。</p><p><img src="https://itsfoss.com/content/images/2023/11/adding-keyboard-layout-1-1.png" alt="There are more keyboard layouts available"></p><p>單擊你想要的鍵盤佈局。請記住，所選的鍵盤佈局可能有子佈局。</p><p>例如，當我單擊<strong>英語（印度）</strong>時，它會向我顯示從丹麥到加納等的一些英語鍵盤佈局。在這裏，我選擇了<strong>英語（印度，盧比）</strong>鍵盤。這是將要添加的鍵盤佈局。</p><p><img src="https://itsfoss.com/content/images/2023/11/new-keyboard-layout-added-ubuntu-1.png" alt=""></p><p>你將在“輸入源”下看到新添加的鍵盤佈局。</p><p><img src="https://itsfoss.com/content/images/2023/11/multiple-keyboards-ubuntu.png" alt=""></p>',16)),n("p",null,[t[4]||(t[4]=s("這與我之前在 ",-1)),e(o,{href:"https://itsfoss.com/type-indian-languages-ubuntu/"},{default:u(()=>[...t[3]||(t[3]=[s("Ubuntu 中添加印地語鍵盤佈局",-1)])]),_:1}),t[5]||(t[5]=s(" 時使用的方法相同。",-1))]),t[33]||(t[33]=n("h3",{id:"步驟-2-切換鍵盤佈局",tabindex:"-1"},[s("步驟 2：切換鍵盤佈局 "),n("a",{class:"header-anchor",href:"#步驟-2-切換鍵盤佈局","aria-label":"Permalink to “步驟 2：切換鍵盤佈局”"},"​")],-1)),t[34]||(t[34]=n("p",null,"這樣，你就成功添加了另一個鍵盤佈局。但它沒有被使用。你必須在可用的輸入源之間切換。",-1)),t[35]||(t[35]=n("p",null,"有兩種方法可以做到這一點。",-1)),t[36]||(t[36]=n("h4",{id:"方法-1-同時使用-super-space-鍵",tabindex:"-1"},[s("方法 1：同時使用 Super+Space 鍵 "),n("a",{class:"header-anchor",href:"#方法-1-同時使用-super-space-鍵","aria-label":"Permalink to “方法 1：同時使用 Super+Space 鍵”"},"​")],-1)),n("p",null,[t[7]||(t[7]=s("切換鍵盤佈局的更快方法是 ",-1)),e(o,{href:"https://itsfoss.com/ubuntu-shortcuts/"},{default:u(()=>[...t[6]||(t[6]=[s("使用鍵盤快捷鍵",-1)])]),_:1}),t[8]||(t[8]=s(" ，同時按 ",-1)),t[9]||(t[9]=n("code",null,"Super",-1)),t[10]||(t[10]=s(" 鍵（Windows 鍵）和空格鍵。它將立即顯示所有啓用的鍵盤佈局。",-1))]),t[37]||(t[37]=a('<p><img src="https://itsfoss.com/content/images/2023/11/switch-keyboard-layout-using-keyboard-shortcut-in-ubuntu.png" alt=""></p><p>你可以在按住 <code>Super</code> 鍵的同時多次按空格鍵在可用選項之間移動。</p><h4 id="方法-2-使用鼠標切換鍵盤佈局" tabindex="-1">方法 2：使用鼠標切換鍵盤佈局 <a class="header-anchor" href="#方法-2-使用鼠標切換鍵盤佈局" aria-label="Permalink to “方法 2：使用鼠標切換鍵盤佈局”">​</a></h4><p>記住所有這些鍵盤快捷鍵並不容易，這是可以理解的。</p><p>當你在系統上啓用多個鍵盤佈局時，你會注意到鍵盤佈局名稱顯示在面板的右上角。單擊它，你將看到在佈局之間切換的選項或查看所選的鍵盤佈局。</p><p><img src="https://itsfoss.com/content/images/2023/11/switching-keyboard-layout-ubuntu-1.png" alt="Switch between keyboard layouts"></p><h3 id="額外提示-刪除額外的鍵盤佈局" tabindex="-1">額外提示：刪除額外的鍵盤佈局 <a class="header-anchor" href="#額外提示-刪除額外的鍵盤佈局" aria-label="Permalink to “額外提示：刪除額外的鍵盤佈局”">​</a></h3><p>不喜歡系統中的多個鍵盤佈局？ 不用擔心。你可以輕鬆刪除它們。</p><p>如你之前所見，再次進入鍵盤設置。單擊你選擇的鍵盤旁邊的三個垂直點符號。你應該在這裏看到刪除選項。</p><p><img src="https://itsfoss.com/content/images/2023/11/remove-additional-keyboard-layout-ubuntu-1.png" alt=""></p><h3 id="使用命令列更改鍵盤佈局-不推薦" tabindex="-1">使用命令列更改鍵盤佈局（不推薦） <a class="header-anchor" href="#使用命令列更改鍵盤佈局-不推薦" aria-label="Permalink to “使用命令列更改鍵盤佈局（不推薦）”">​</a></h3><p>如果你是桌面用户，我強烈推薦上面討論的圖形方法。</p><p>如果你在服務器上並且必須使用其他鍵盤佈局，則可以選擇命令列。</p>',13)),n("p",null,[t[12]||(t[12]=s("現在，有多種方法可以更改 Linux 中的鍵盤佈局。但對於 Ubuntu，我更喜歡 ",-1)),e(o,{href:"https://wiki.debian.org/dpkg"},{default:u(()=>[...t[11]||(t[11]=[s("dpkg",-1)])]),_:1}),t[13]||(t[13]=s(" 方式。",-1))]),t[38]||(t[38]=a('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg-reconfigure keyboard-configuration</span></span></code></pre></div><p>輸入你的密碼，你將在終端中看到：</p><p><img src="https://itsfoss.com/content/images/2023/11/changing-keyboard-layout-ubuntu-command-line.png" alt=""></p><p>要在此 TUI（終端用户界面）中導航，請使用箭頭鍵在可用選項之間移動。<strong>使用 <code>Tab</code> 鍵轉至 “OK” 或 “Cancel” 選項</strong>。當你位於其中之一時，請按回車鍵確認你的選擇。</p><p>選擇你選擇的國家/地區，然後你可以選擇鍵盤佈局。</p><p><img src="https://itsfoss.com/content/images/2023/11/adding-keyboard-ubuntu-command-line-1.png" alt=""></p><p>添加附加鍵盤後，系統會要求你分配鍵盤快捷鍵以在它們之間進行切換。</p><p><img src="https://itsfoss.com/content/images/2023/11/keyboard-switch-option.png" alt=""></p><p>你也可以將新鍵盤佈局設置為系統中的默認佈局和唯一佈局。不過，如果你在不相似的語言之間執行此操作，這可能會存在風險。我的意思是，如果你使用英語美國鍵盤（物理）並將佈局切換為匈牙利語，則你將無法使用所有按鍵。</p><p>之後你會看到幾個屏幕。</p><p>如果你對新的鍵盤佈局不滿意，可以再次鍵入相同的命令，然後重新配置佈局。</p><p><em>（題圖：MJ/f03362cf-72d0-4003-b334-44c533e113a0）</em></p><hr>',13)),n("p",null,[t[15]||(t[15]=s("via: ",-1)),e(o,{href:"https://itsfoss.com/ubuntu-change-keyboard/"},{default:u(()=>[...t[14]||(t[14]=[s("https://itsfoss.com/ubuntu-change-keyboard/",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=s("作者：",-1)),e(o,{href:"https://itsfoss.com/author/abhishek/"},{default:u(()=>[...t[16]||(t[16]=[s("Abhishek Prakash",-1)])]),_:1}),t[21]||(t[21]=s(" 選題：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:u(()=>[...t[17]||(t[17]=[s("lujun9972",-1)])]),_:1}),t[22]||(t[22]=s(" 譯者：",-1)),e(o,{href:"https://github.com/geekpi"},{default:u(()=>[...t[18]||(t[18]=[s("geekpi",-1)])]),_:1}),t[23]||(t[23]=s(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:u(()=>[...t[19]||(t[19]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[26]||(t[26]=s("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[24]||(t[24]=[s("LCTT",-1)])]),_:1}),t[27]||(t[27]=s(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:u(()=>[...t[25]||(t[25]=[s("Linux中國",-1)])]),_:1}),t[28]||(t[28]=s(" 榮譽推出",-1))])])}const x=i(d,[["render",b]]);export{C as __pageData,x as default};
